    s += T(left + w + 16, top + 90, 'log d^K ≈ ' + fmt(d.K.logDifferentEstimate), { size: 10.5, color: C.hull }); s += T(left + w + 16, top + 106, 'log q = ' + fmt(rep.logQ), { size: 10.5, color: C.theta });
    s += T(left + w + 16, top + 130, '÷ l*: −|log Θ| heuristic', { size: 10.5, color: C.dim }); s += T(left + w + 16, top + 146, fmt(rep.thetaUpperBound), { size: 12, mono: true, bold: true });
    s += T(left + w + 16, top + 170, '−|log q| = −log q / 2l', { size: 10.5, color: C.dim }); s += T(left + w + 16, top + 186, fmt(-rep.AbsLogQ), { size: 12, mono: true, bold: true });
